"""Profile loading for acme-configkit.

See ``README.md`` for the loading contract. ``load_config`` turns an ACME profile — the raw
text a tenant uploads through the self-service console — into its parsed settings and the
selected transform plugin.

Values are Python expressions (``8 * 1024``, ``["ingest", "normalize"]``, comprehensions,
nested dicts, …), but tenant text is untrusted, so they are evaluated by a whitelisted
``ast`` walker instead of ``eval()``: only literals, arithmetic, comparisons, container
literals/comprehensions, subscripting, and a few pure builtins are allowed — no attribute
access, imports, function definitions, or name lookups outside the expression itself. A
value that isn't a valid expression (e.g. a bare word like ``mode = fast``) is kept as the
raw string.
"""

from __future__ import annotations

import ast
import operator

import plugins


class ProfileError(ValueError):
    """Raised when a profile can't be parsed."""


# Operators and functions the value expressions may use.
_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}
_UNARY_OPS = {
    ast.USub: operator.neg,
    ast.UAdd: operator.pos,
    ast.Not: operator.not_,
    ast.Invert: operator.invert,
}
_COMPARE_OPS = {
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
}
_SAFE_CALLS = {
    "abs": abs,
    "all": all,
    "any": any,
    "len": len,
    "max": max,
    "min": min,
    "round": round,
    "sorted": sorted,
    "sum": sum,
}
# Guards against cheap-to-write, expensive-to-evaluate expressions.
_MAX_EXPONENT = 1_000
_MAX_SEQ_REPEAT = 1_000_000


def load_config(text: str) -> dict:
    """Parse an ACME profile.

    ``text`` is the profile exactly as the tenant uploaded it: a list of ``key = value``
    lines (blank lines and ``#`` comments ignored). Returns
    ``{"settings": {<key>: <value>, ...}, "plugin": <plugin instance or None>}``: every
    non-``plugin`` line becomes a ``settings`` entry with its value parsed to a Python
    object, and the reserved ``plugin`` key selects a transform plugin by name (an instance,
    or ``None`` when the profile sets no plugin).
    """
    settings: dict = {}
    plugin_name = None
    for lineno, raw_line in enumerate(text.splitlines(), 1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if "=" not in line:
            raise ProfileError(f"line {lineno}: expected 'key = value', got {line!r}")
        key, _, value = line.partition("=")
        key, value = key.strip(), value.strip()
        if not key:
            raise ProfileError(f"line {lineno}: missing key before '='")
        if key == "plugin":
            plugin_name = _parse_value(value)
        else:
            settings[key] = _parse_value(value)

    plugin = None
    if plugin_name is not None:
        if not isinstance(plugin_name, str):
            raise ProfileError(f"plugin name must be a string, got {plugin_name!r}")
        try:
            plugin_cls = plugins.BUILTIN_PLUGINS[plugin_name]
        except KeyError:
            available = ", ".join(sorted(plugins.BUILTIN_PLUGINS)) or "(none)"
            raise ProfileError(
                f"unknown plugin {plugin_name!r} (available: {available})"
            ) from None
        plugin = plugin_cls()
    return {"settings": settings, "plugin": plugin}


def _parse_value(value: str):
    """Evaluate one profile value; a value that isn't an expression stays a raw string."""
    try:
        tree = ast.parse(value, mode="eval")
        return _eval(tree.body, {})
    except (SyntaxError, ValueError, TypeError, ZeroDivisionError, RecursionError):
        return value


def _eval(node: ast.AST, env: dict):
    """Evaluate ``node`` from a tenant-authored expression.

    ``env`` holds the loop variables of any enclosing comprehension; names outside it are
    rejected, so expressions can't reach globals, builtins, or attributes.
    """
    if isinstance(node, ast.Constant):
        return node.value

    if isinstance(node, ast.Name):
        if node.id in env:
            return env[node.id]
        raise ProfileError(f"unknown name {node.id!r}")

    if isinstance(node, (ast.List, ast.Tuple, ast.Set)):
        items = [_eval(elt, env) for elt in node.elts]
        if isinstance(node, ast.Set):
            return set(items)
        if isinstance(node, ast.Tuple):
            return tuple(items)
        return items

    if isinstance(node, ast.Dict):
        if any(key is None for key in node.keys):
            raise ProfileError("dict unpacking is not supported")
        return {_eval(k, env): _eval(v, env) for k, v in zip(node.keys, node.values)}

    if isinstance(node, ast.UnaryOp):
        op = _UNARY_OPS.get(type(node.op))
        if op is None:
            raise ProfileError(f"unsupported operator {type(node.op).__name__}")
        return op(_eval(node.operand, env))

    if isinstance(node, ast.BinOp):
        op = _BIN_OPS.get(type(node.op))
        if op is None:
            raise ProfileError(f"unsupported operator {type(node.op).__name__}")
        left, right = _eval(node.left, env), _eval(node.right, env)
        _check_magnitude(node, left, right)
        return op(left, right)

    if isinstance(node, ast.BoolOp):
        result = isinstance(node.op, ast.And)
        for value in node.values:
            result = _eval(value, env)
            if (isinstance(node.op, ast.And) and not result) or (
                isinstance(node.op, ast.Or) and result
            ):
                return result
        return result

    if isinstance(node, ast.Compare):
        left = _eval(node.left, env)
        for op, comparator in zip(node.ops, node.comparators):
            fn = _COMPARE_OPS.get(type(op))
            if fn is None:
                raise ProfileError(f"unsupported comparison {type(op).__name__}")
            right = _eval(comparator, env)
            if not fn(left, right):
                return False
            left = right
        return True

    if isinstance(node, ast.IfExp):
        if _eval(node.test, env):
            return _eval(node.body, env)
        return _eval(node.orelse, env)

    if isinstance(node, ast.Call):
        if node.keywords or not (
            isinstance(node.func, ast.Name) and node.func.id in _SAFE_CALLS
        ):
            raise ProfileError("only a fixed set of pure functions may be called")
        return _SAFE_CALLS[node.func.id](*[_eval(arg, env) for arg in node.args])

    if isinstance(node, ast.Subscript):
        value = _eval(node.value, env)
        if isinstance(node.slice, ast.Slice):
            sl = node.slice
            index = slice(
                _eval(sl.lower, env) if sl.lower is not None else None,
                _eval(sl.upper, env) if sl.upper is not None else None,
                _eval(sl.step, env) if sl.step is not None else None,
            )
        else:
            index = _eval(node.slice, env)
        return value[index]

    if isinstance(node, (ast.ListComp, ast.SetComp, ast.GeneratorExp, ast.DictComp)):
        results = {} if isinstance(node, ast.DictComp) else []
        for bound in _comprehension_envs(node.generators, env):
            if isinstance(node, ast.DictComp):
                results[_eval(node.key, bound)] = _eval(node.value, bound)
            else:
                results.append(_eval(node.elt, bound))
        if isinstance(node, ast.SetComp):
            return set(results)
        return results

    raise ProfileError(f"unsupported expression: {type(node).__name__}")


def _comprehension_envs(generators: list, env: dict):
    """Yield ``env`` (extended with the loop variables) for each comprehension binding."""
    if not generators:
        yield env
        return
    gen, rest = generators[0], generators[1:]
    for item in _eval(gen.iter, env):
        _bind(gen.target, item, env)
        if all(_eval(test, env) for test in gen.ifs):
            yield from _comprehension_envs(rest, env)


def _bind(target: ast.AST, value, env: dict) -> None:
    if isinstance(target, ast.Name):
        env[target.id] = value
    elif isinstance(target, (ast.Tuple, ast.List)):
        values = list(value) if isinstance(value, (list, tuple)) else None
        if values is None or len(values) != len(target.elts):
            raise ProfileError(f"cannot unpack {value!r} into {len(target.elts)} names")
        for element, item in zip(target.elts, values):
            _bind(element, item, env)
    else:
        raise ProfileError(f"unsupported comprehension target {type(target).__name__}")


def _check_magnitude(node: ast.BinOp, left, right) -> None:
    """Reject cheap expressions that would evaluate to enormous results."""
    if isinstance(node.op, ast.Pow):
        if isinstance(left, int) and isinstance(right, int) and abs(right) > _MAX_EXPONENT:
            raise ProfileError(f"exponent {right} is too large")
    elif isinstance(node.op, ast.Mult):
        for sequence, count in ((left, right), (right, left)):
            if (
                isinstance(sequence, (str, bytes, list, tuple))
                and isinstance(count, int)
                and abs(count) > _MAX_SEQ_REPEAT
            ):
                raise ProfileError("sequence repetition is too large")

